import 'package:equatable/equatable.dart';

/// An inbox entry (`GET /notifications`). The body is generated by the
/// backend ("Kato Builders uploaded Walling evidence at 10:58 AM, 14 Oct.")
/// and shown straight from memory — there is no detail endpoint.
class AppNotification extends Equatable {
  const AppNotification({
    required this.notificationId,
    required this.title,
    required this.body,
    required this.isRead,
    this.createdAt,
  });

  final String notificationId;
  final String title;
  final String body;
  final bool isRead;
  final DateTime? createdAt;

  AppNotification copyWith({bool? isRead}) => AppNotification(
    notificationId: notificationId,
    title: title,
    body: body,
    isRead: isRead ?? this.isRead,
    createdAt: createdAt,
  );

  @override
  List<Object?> get props => [notificationId, title, body, isRead, createdAt];
}

enum DevicePlatform {
  android('ANDROID'),
  ios('IOS');

  const DevicePlatform(this.apiValue);

  final String apiValue;
}
